36	use ignore::types::TypesBuilder;
37	
38	let mut builder = TypesBuilder::new();
39	builder.add_defaults();
40	builder.negate("c");
41	let matcher = builder.build().unwrap();
42	
43	assert!(matcher.matched("foo.rs", false).is_none());
